#include <vector>

// std::vector<bool>::operator[] does not return a bool&.
// It returns a proxy object of type std::vector<bool>::reference.
std::vector<bool> getPermissions() { return {true, false, true}; }

auto perms = getPermissions();

// 'auto' deduces the proxy type, not bool.
auto canExecute = perms[2]; // Type of canExecute is std::vector<bool>::reference

// This can lead to unexpected behavior or errors.
// For example, its address is not the address of a bool element in the vector.
// bool *p = &canExecute; // COMPILE ERROR

// The 'explicitly typed initializer idiom' forces the desired type.
// The proxy object is converted to bool during initialization.
auto canExecuteAsBool = static_cast<bool>(perms[2]); // Now the type is bool
